INSERT INTO m240_art VALUES
(0,0,$m240$الديباجة$m240$,$m240$قانون رقم 27 لسنة 1994 بإصدار قانون فى شأن التحكيم فى المواد المدنية والتجارية
باسم الشعب رئيس الجمهورية قرر مجلس الشعب القانون الآتى نصه ، وقد أصدرناه :$m240$,'d25a93408effeda0016e02347c502ad4'),
(1,-1,$m240$المادة الأولى إصدار$m240$,$m240$يعمل بأحكام القانون المرافق على كل تحكيم قائم وقت نفاذه أو يبدأ بعد نفاذه ولو استند إلى اتفاق تحكيم سبق إبرامه قبل نفاذ هذا القانون .$m240$,'eb64c307e39c676419e69f3337a31fb6'),
(2,-1,$m240$المادة الثانية إصدار$m240$,$m240$يصدر وزير العدل القرارات اللازمة لتنفيذ أحكام هذا القانون . ويضع قوائم المحكمين الذين يجرى الاختيار من بينهم وفقا لحكم المادة ( 17 ) من هذا القانون .$m240$,'1ed7312029bd0b68926ef23bd31d15b6'),
(3,-1,$m240$المادة الثالثة إصدار$m240$,$m240$تلغى المواد من 501 إلى 513 من القانون رقم 13 لسنة 1968 بإصدار قانون المرافعات المدنية والتجارية ، كما يلغى أى حكم مخالف لأحكام هذا القانون .$m240$,'5d125ddb86279649e35693508f70c44f'),
(4,-1,$m240$المادة الرابعة إصدار$m240$,$m240$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به بعد شهر من اليوم التالى لتاريخ نشره .
يبصم هذا القانون بخاتم الدولة ، وينفذ كقانون من قوانينها .
صدر برئاسة الجمهورية فى 7 ذى القعدة سنة 1414 هـ الموافق 18 أبريل سنة 1994 م
حسنى مبارك$m240$,'d2c963435ba518c82145d9a2d753ecdb'),
(1,0,$m240$المادة 1$m240$,$m240$مع عدم الإخلال بأحكام الاتفاقيات الدولية المعمول بها فى جمهورية مصر العربية تسرى أحكام هذا القانون على كل تحكيم بين أطراف من أشخاص القانون العام أو القانون الخاص أيا كانت طبيعة العلاقة القانونية التى يدور حولها النزاع اذا كان هذا التحكيم يجرى فى مصر ، أو كان تحكيما تجاريا دوليا يجرى فى الخارج واتفق أطرافه على اخضاعه لأحكام هذا القانون .$m240$,'b4cb799a088c5a94598460264c24e522'),
(2,0,$m240$المادة 2$m240$,$m240$يكون التحكيم تجاريا فى حكم هذا القانون إذا نشأ النزاع حول علاقة قانونية ذات طابع اقتصادى ، عقدية كانت أو غير عقدية ، ويشمل ذلك على سبيل المثال توريد السلع أو الخدمات والوكالات التجارية وعقود التشييد والخبرة الهندسية أو الفنية ومنح التراخيص الصناعية والسياحية وغيرها ونقل التكنولوجيا والاستثمار وعقود التنمية وعمليات البنوك والتأمين والنقل وعمليات تنقيب واستخراج الثروات الطبيعية وتوريد الطاقة ومد أنابيب الغاز أو النفط وشق الطرق والانفاق واستصلاح الأراضى الزراعية وحماية البيئة وإقامة المفاعلات النووية .$m240$,'bc07e36b7a3d4df4f6f90886ad2270c1'),
(3,0,$m240$المادة 3$m240$,$m240$يكون التحكيم دوليا فى حكم هذا القانون إذا كان موضوعه نزاعا يتعلق بالتجارة الدولية وذلك فى الأحوال الآتية :
أولا : اذا كان المركز الرئيسى لأعمال كل من طرفى التحكيم يقع فى دولتين مختلفتين وقت إبرام اتفاق التحكيم . فإذا كان لأحد الطرفين عدة مراكز للأعمال فالعبرة بالمركز الأكثر ارتباطا بموضوع اتفاق التحكيم . وإذا لم يكن لأحد طرفى التحكيم مركز أعمال فالعبرة بمحل إقامته المعتاد .
ثانيا : إذا اتفق طرفا التحكيم على اللجوء إلى منظمة تحكيم دائمة أو مركز للتحكيم يوجد مقره داخل جمهورية مصر العربية أو خارجها .
ثالثا : إذا كان موضوع النزاع الذى يشمله اتفاق التحكيم يرتبط بأكثر من دولة واحدة .
رابعا : اذا كان المركز الرئيسى لأعمال كل من طرفى التحكيم يقع فى نفس الدولة وقت إبرام اتفاق التحكيم وكان أحد الأماكن التالية واقعا خارج هذه الدولة :
( أ ) مكان إجراء التحكيم كما عينه اتفاق التحكيم أو أشار إلى كيفية تعيينه .
( ب ) مكان تنفيذ جانب جوهرى من الالتزامات الناشئة عن العلاقة التجارية بين الطرفين .
( جـ ) المكان الأكثر ارتباطا بموضوع النزاع .$m240$,'6fb32cfdaf971c36e03c7a660055d07f'),
(4,0,$m240$المادة 4$m240$,$m240$( 1 ) ينصرف لفظ : « التحكيم » فى حكم هذا القانون إلى التحكيم الذى يتفق عليه طرفا النزاع بارادتهما الحرة سواء كانت الجهة التى تتولى إجراءات التحكيم ، بمقتضى اتفاق الطرفين ، منظمة أو مركز دائم للتحكيم أو لم يكن كذلك .
( 2 ) وتنصرف عبارة : « هيئة التحكيم » إلى الهيئة المشكلة من محكم واحد أو أكثر للفصل فى النزاع المحال إلى التحكيم . أما لفظ « المحكمة » فينصرف إلى المحكمة التابعة للنظام القضائى فى الدولة .
( 3 ) وتنصرف عبارة « طرفى التحكيم » فى هذا القانون إلى أطراف التحكيم ولو تعددوا .$m240$,'c1b283fd9028c0ff48967069859aedf9'),
(5,0,$m240$المادة 5$m240$,$m240$فى الأحوال التى يجيز فيها هذا القانون لطرفى التحكيم اختيار الإجراء الواجب الاتباع فى مسألة معينة تضمن ذلك حقهما فى الترخيص للغير فى اختيار هذا الإجراء ، ويعتبر من الغير فى هذا الشأن كل منظمة أو مركز للتحكيم فى جمهورية مصر العربية أو فى خارجها .$m240$,'ab2aca9bd8d1787f445a60b8fb9f95a0'),
(6,0,$m240$المادة 6$m240$,$m240$إذا اتفق طرفا التحكيم على إخضاع العلاقة القانونية بينهما لأحكام عقد نموذجى أو اتفاقية دولية أو أية وثيقة أخرى . وجب العمل بأحكام هذه الوثيقة بما تشمله من أحكام خاصة بالتحكيم .$m240$,'7e7c781fb0db48e3cc8bfa672c49a39d'),
(7,0,$m240$المادة 7$m240$,$m240$( 1 ) ما لم يوجد اتفاق خاص بين طرفى التحكيم ، يتم تسليم أى رسالة أو إعلان إلى المرسل اليه شخصيا أو فى مقر عمله أو فى محل إقامته المعتاد أو فى عنوانه البريدى المعروف للطرفين أو المحدد فى مشارطة التحكيم أو فى الوثيقة المنظمة للعلاقة التى يتناولها التحكيم .
( 2 ) وإذا تعذر معرفة أحد هذين العنوانين بعد إجراء التحريات اللازمة ، يعتبر التسليم قد تم إذا كان الإعلان بكتاب مسجل إلى آخر مقر عمل أو محل إقامة معتاد أو عنوان بريدى معروف للمرسل إليه .
( 3 ) لا تسرى أحكام هذه المادة على الإعلانات القضائية أمام المحاكم .$m240$,'f64bf60933b176600ca850b84be29c40'),
(8,0,$m240$المادة 8$m240$,$m240$إذا استمر أحد طرفى النزاع فى إجراءات التحكيم مع علمه بوقوع مخالفة لشرط فى اتفاق التحكيم أو لحكم من أحكام هذا القانون مما يجوز الاتفاق على مخالفته ولم يقدم اعتراضا على هذه المخالفة فى الميعاد المتفق عليه أو فى وقت معقول عند عدم الاتفاق ، اعتبر ذلك نزولا منه عن حقه فى الاعتراض .$m240$,'a64fef5b3de119023c3f0861219dfa4b'),
(9,0,$m240$المادة 9$m240$,$m240$( 1 ) يكون الاختصاص بنظر مسائل التحكيم التى يحيلها هذا القانون إلى القضاء المصرى للمحكمة المختصة أصلا بنظر النزاع . أما إذا كان التحكيم تجاريا دوليا ، سواء جرى فى مصر أو فى الخارج ، فيكون الاختصاص لمحكمة استئناف القاهرة ما لم يتفق الطرفان على اختصاص محكمة استئناف أخرى فى مصر .
( 2 ) وتظل المحكمة التى ينعقد لها الاختصاص وفقا للفقرة السابقة دون غيرها صاحبة الاختصاص حتى انتهاء جميع إجراءات التحكيم .$m240$,'7c8a1a8ddf6328994e2becfc02e0077d'),
(10,0,$m240$المادة 10$m240$,$m240$( 1 ) اتفاق التحكيم هو اتفاق الطرفين على الالتجاء إلى التحكيم لتسوية كل أو بعض المنازعات التى نشأت أو يمكن أن تنشأ بينهما بمناسبة علاقة قانونية معينة عقدية كانت أو غير عقدية .
( 2 ) يجوز أن يكون اتفاق التحكيم سابقا على قيام النزاع سواء قام مستقلا بذاته أو ورد فى عقد معين بشأن كل أو بعض المنازعات التى قد تنشأ بين الطرفين ، وفى هذه الحالة يجب أن يحدد موضوع النزاع فى بيان الدعوى المشار اليه فى الفقرة الأولى من المادة ( 30 ) من هذا القانون ، كما يجوز أن يتم اتفاق التحكيم بعد قيام النزاع ولو كانت قد أقيمت فى شأنه دعوى أمام جهة قضائية ، وفى هذه الحالة يجب أن يحدد الاتفاق المسائل التى يشملها التحكيم وإلا كان الاتفاق باطلا .
( 3 ) ويعتبر اتفاقا على التحكيم كل إحالة ترد فى العقد إلى وثيقة تتضمن شرط تحكيم إذا كانت الإحالة واضحة فى اعتبار هذا الشرط جزءا من العقد .$m240$,'02bf10f3f0b22b385da0edb29a41c63c'),
(11,0,$m240$المادة 11$m240$,$m240$لا يجوز الاتفاق على التحكيم إلا للشخص الطبيعى أو الاعتبارى الذى يملك التصرف فى حقوقه ، ولا يجوز التحكيم فى المسائل التى لا يجوز فيها الصلح .$m240$,'0873b26e950908955780cc619e4fb8f8'),
(12,0,$m240$المادة 12$m240$,$m240$يجب أن يكون اتفاق التحكيم مكتوبا وإلا كان باطلا . ويكون اتفاق التحكيم مكتوبا إذا تضمنه محرر وقعه الطرفان أو إذا تضمنه ما تبادله الطرفان من رسائل أو برقيات أو غيرها من وسائل الاتصال المكتوبة .$m240$,'b459c5f79a06a0db318cb59236fb20f4'),
(13,0,$m240$المادة 13$m240$,$m240$( 1 ) يجب على المحكمة التى يرفع إليها نزاع يوجد بشأنه اتفاق تحكيم أن تحكم بعدم قبول الدعوى إذا دفع المدعى عليه بذلك قبل إبدائه أى طلب أو دفاع فى الدعوى .
( 2 ) ولا يحول رفع الدعوى المشار إليها فى الفقرة السابقة دون البدء فى إجراءات التحكيم أو الاستمرار فيها أو إصدار حكم التحكيم .$m240$,'a11ba22abbb1f31a057f368b1b6f6400'),
(14,0,$m240$المادة 14$m240$,$m240$يجوز للمحكمة المشار اليها فى المادة ( 9 ) من هذا القانون أن تأمر ، بناء على طلب أحد طرفى التحكيم ، باتخاذ تدابير مؤقتة أو تحفظية سواء قبل البدء فى إجراءات التحكيم أو أثناء سيرها .$m240$,'5dfc2aca404d8bed9bdce28608f2852b'),
(15,0,$m240$المادة 15$m240$,$m240$( 1 ) تشكل هيئة التحكيم باتفاق الطرفين من محكم واحد أو أكثر ، فإذا لم يتفقا على عدد المحكمين كان العدد ثلاثة .
( 2 ) إذا تعدد المحكمون وجب أن يكون عددهم وترا ، وإلا كان التحكيم باطلا .$m240$,'b5ae9b5bc7c804c2b82cee102d84bcbc'),
(16,0,$m240$المادة 16$m240$,$m240$( 1 ) لا يجوز أن يكون المحكم قاصرا أو محجورا عليه أو محروما من حقوقه المدنية بسبب الحكم عليه فى جناية أو جنحة مخلة بالشرف أو بسبب شهر إفلاسه ما لم يرد إليه اعتباره .
( 2 ) لا يشترط أن يكون المحكم من جنس أو جنسية معينة إلا إذا اتفق طرفا التحكيم أو نص القانون على غير ذلك .
( 3 ) يكون قبول المحكم القيام بمهمته كتابة ، ويجب عليه أن يفصح عند قبوله عن أية ظروف من شأنها إثارة شكوك حول استقلاله أو حيدته .$m240$,'6ae1bc97959d0b2f699e1bc21366a7cf'),
(17,0,$m240$المادة 17$m240$,$m240$( 1 ) لطرفى التحكيم الاتفاق على اختيار المحكمين وعلى كيفية ووقت اختيارهم فإذا لم يتفقا اتبع ما يأتى :
( أ ) إذا كانت هيئة التحكيم مشكلة من محكم واحد تولت المحكمة المشار إليها فى المادة ( 9 ) من هذا القانون اختياره بناء على طلب أحد الطرفين .
( ب ) فإذا كانت هيئة التحكيم مشكلة من ثلاثة محكمين اختار كل طرف محكما ثم يتفق المحكمان على اختيار المحكم الثالث ، فإذا لم يعين أحد الطرفين محكمه خلال الثلاثين يوما التالية لتسلمه طلبا بذلك من الطرف الآخر ، أو إذا لم يتفق المحكمان المعينان على اختيار المحكم الثالث خلال الثلاثين يوما التالية لتاريخ تعيين آخرهما ، تولت المحكمة المشار إليها فى المادة ( 9 ) من هذا القانون اختياره بناء على طلب أحد الطرفين . ويكون للمحكم الذى اختاره المحكمان المعينان أو الذى اختارته المحكمة رئاسة هيئة التحكيم ، وتسرى هذه الأحكام فى حالة تشكيل هيئة التحكيم من أكثر من ثلاثة محكمين .
( 2 ) وإذا خالف أحد الطرفين إجراءات اختيار المحكمين التى اتفقا عليها ، أو لم يتفق المحكمان المعينان على أمر مما يلزم اتفاقهما عليه ، أو إذا تخلف الغير عن أداء ما عهد به إليه فى هذا الشأن ، تولت المحكمة المشار إليها فى المادة ( 9 ) من هذا القانون بناء على طلب أحد الطرفين ، القيام بالإجراء أو بالعمل المطلوب ما لم ينص فى الاتفاق على كيفية أخرى لإتمام هذا الإجراء أو العمل .
( 3 ) وتراعى المحكمة فى المحكم الذى تختاره الشروط التى يتطلبها هذا القانون وتلك التى اتفق عليها الطرفان ، وتصدر قرارها باختيار المحكم على وجه السرعة ، ومع عدم الإخلال بأحكام المادتين 18 و 19 من هذا القانون لايقبل هذا القرار الطعن فيه بأى طريق من طرق الطعن .$m240$,'39959964695c06e4c8224d0fd3631177'),
(18,0,$m240$المادة 18$m240$,$m240$( 1 ) لا يجوز رد المحكم إلا إذا قامت ظروف تثير شكوكا جدية حول حيدته أو استقلاله .
( 2 ) ولا يجوز لأى من طرفى التحكيم رد المحكم الذى عينه أو اشترك فى تعيينه إلا لسبب تبينه بعد أن تم هذا التعيين .$m240$,'07395fcaef51a8115d6a8dd462ef883a'),
(19,0,$m240$المادة 19$m240$,$m240$( 1 ) يقدم طلب الرد كتابة إلى هيئة التحكيم مبينا فيه أسباب الرد خلال خمسة عشر يوما من تاريخ علم طالب الرد بتشكيل هذه الهيئة أو بالظروف المبررة للرد ، فإذا لم يتنح المحكم المطلوب رده فصلت هيئة التحكيم فى الطلب .
( 2 ) ولا يقبل الرد ممن سبق له تقديم طلب برد المحكم نفسه فى ذات التحكيم .
( 3 ) لطالب الرد أن يطعن فى الحكم برفض طلبه خلال ثلاثين يوما من تاريخ إعلانه به أمام المحكمة المشار اليها فى المادة ( 9 ) من هذا القانون ، ويكون حكمها غير قابل للطعن بأى طريق .
( 4 ) لا يترتب على تقديم طلب الرد أو على الطعن فى حكم التحكيم الصادر برفضه وقف إجراءات التحكيم وإذا حكم برد المحكم ؛ سواء من هيئة التحكيم أو من المحكمة عند نظر الطعن ، ترتب على ذلك اعتبار ما يكون قد تم من إجراءات التحكيم ، بما فى ذلك حكم المحكمين ، كأن لم يكن .$m240$,'6a73c4fb2bd0d6373746db45dc68f543'),
(20,0,$m240$المادة 20$m240$,$m240$إذا تعذر على المحكم أداء مهمته أو لم يباشرها أو انقطع عن أدائها بما يؤدى إلى تأخير لا مبرر له فى إجراءات التحكيم ولم يتنح ولم يتفق الطرفان على عزله ، جاز للمحكمة المشار إليها فى المادة ( 9 ) من هذا القانون الأمر بإنهاء مهمته بناء على طلب أى من الطرفين .$m240$,'f0760d25da80b4ab479841d6bac7d462'),
(21,0,$m240$المادة 21$m240$,$m240$إذا انتهت مهمة المحكم بالحكم برده أو عزله أو تنحيه أو بأى سبب آخر ، وجب تعيين بديل له طبقا للإجراءات التى تتبع فى اختيار المحكم الذى انتهت مهمته .$m240$,'ebdc286565f54727792f119725fbd7a5'),
(22,0,$m240$المادة 22$m240$,$m240$( 1 ) تفصل هيئة التحكيم فى الدفوع المتعلقة بعدم اختصاصها بما فى ذلك الدفوع المبنية على عدم وجود اتفاق تحكيم أو سقوطه أو بطلانه أو عدم شموله لموضوع النزاع .
( 2 ) يجب التمسك بهذه الدفوع فى ميعاد لا يجاوز ميعاد تقديم دفاع المدعى عليه المشار إليه فى الفقرة الثانية من المادة ( 30 ) من هذا القانون ولا يترتب على قيام أحد طرفى التحكيم بتعيين محكم أو الاشتراك فى تعيينه سقوط حقه فى تقديم أى من هذه الدفوع . أما الدفع بعدم شمول اتفاق التحكيم لما يثيره الطرف الآخر من مسائل أثناء نظر النزاع فيجب التمسك به فورا
وإلا سقط الحق فيه . ويجوز ، فى جميع الأحوال - أن تقبل هيئة التحكيم الدفع المتأخر إذا رأت أن التأخير كان لسبب مقبول .
( 3 ) تفصل هيئة التحكيم فى الدفوع المشار إليها فى الفقرة الأولى من هذه المادة قبل الفصل فى الموضوع أو أن تضمها إلى الموضوع لتفصل فيهما معا . فإذا قضت برفض الدفع ، فلا يجوز التمسك به إلا بطريق رفع دعوى بطلان حكم التحكيم المنهى للخصومة كلها وفقا للمادة ( 53 ) من هذا القانون .$m240$,'085d6780237f1d19e7d997d65444dd5f'),
(23,0,$m240$المادة 23$m240$,$m240$يعتبر شرط التحكيم اتفاقا مستقلا عن شروط العقد الأخرى . ولا يترتب على بطلان العقد أو فسخه أو إنهائه أى أثر على شرط التحكيم الذى يتضمنه ، إذا كان هذا الشرط صحيحا فى ذاته .$m240$,'ae3745d996c1fdda53aafb7b0f3bc500'),
(24,0,$m240$المادة 24$m240$,$m240$( 1 ) يجوز لطرفى التحكيم الاتفاق على أن يكون لهيئة التحكيم ، بناء على طلب أحدهما ، أن تأمر أيا منهما باتخاذ ما تراه من تدابير مؤقتة أو تحفظية تقتضيها طبيعة النزاع ، وأن تطلب تقديم ضمان كاف لتغطية نفقات التدبير الذى تأمر به .
( 2 ) وإذا تخلف من صدر إليه الأمر عن تنفيذه ، جاز لهيئة التحكيم ، بناء على طلب الطرف الآخر ، أن تأذن لهذا الطرف فى اتخاذ الإجراءات اللازمة لتنفيذه ، وذلك دون إخلال بحق هذا الطرف فى أن يطلب من رئيس المحكمة المشار إليها فى المادة ( 9 ) من هذا القانون الأمر بالتنفيذ .$m240$,'106d4b993c1f7179fe174f11a5d8ec9f'),
(25,0,$m240$المادة 25$m240$,$m240$لطرفى التحكيم الاتفاق على الإجراءات التى تتبعها هيئة التحكيم بما فى ذلك حقهما فى إخضاع هذه الإجراءات للقواعد النافذة فى أى منظمة أو مركز تحكيم فى جمهورية مصر العربية أو خارجها فاذا لم يوجد مثل هذا الاتفاق كان لهيئة التحكيم ، مع مراعاه أحكام هذا القانون ، أن تختار إجراءات التحكيم التى تراها مناسبة .$m240$,'ecb22301206e572bdc5d921a69c77914'),
(26,0,$m240$المادة 26$m240$,$m240$يعامل طرفا التحكيم على قدم المساواة وتهيأ لكل منهما فرصة متكافئة وكاملة لعرض دعواه .$m240$,'50e87ee91e82bf83de366ee6641ab1e5'),
(27,0,$m240$المادة 27$m240$,$m240$تبدأ إجراءات التحكيم من اليوم الذى يتسلم فيه المدعى عليه طلب التحكيم من المدعى ، ما لم يتفق الطرفان على موعد آخر .$m240$,'26a0023b4f6f317752ab87488ee892c7'),
(28,0,$m240$المادة 28$m240$,$m240$لطرفى التحكيم الاتفاق على مكان التحكيم فى مصر أو خارجها . فإذا لم يوجد اتفاق عينت هيئة التحكيم مكان التحكيم مع مراعاة ظروف الدعوى وملاءمة المكان لأطرافها . ولا يخل ذلك بسلطة هيئة التحكيم فى أن تجتمع فى أى مكان تراه مناسبا للقيام بإجراء من إجراءات التحكيم كسماع أطراف النزاع أو الشهود أو الخبراء أو الاطلاع على مستندات أو معاينة بضاعة أو أموال أو إجراء مداولة بين أعضائها أو غير ذلك .$m240$,'910ea4b036e580e8ecd2a4cfef3bd7c6'),
(29,0,$m240$المادة 29$m240$,$m240$( 1 ) يجرى التحكيم باللغة العربية ما لم يتفق الطرفان أو تحدد هيئة التحكيم لغة أو لغات أخرى . ويسرى حكم الاتفاق أو القرار على لغة البيانات والمذكرات المكتوبة وعلى المرافعات الشفهية وكذلك على كل قرار تتخذه هذه الهيئة أو رسالة توجهها أو حكم تصدره مالم ينص اتفاق الطرفين أو قرار هيئة التحكيم على غير ذلك .
( 2 ) ولهيئة التحكيم أن تقرر أن يرفق بكل أو بعض الوثائق المكتوبة التى تقدم فى الدعوى ترجمة الى اللغة أو اللغات المستعملة فى التحكيم . وفى حالة تعدد هذه اللغات يجوز قصر الترجمة على بعضها .$m240$,'f60ffa05c3fd7ab639b9676ba622e6c5'),
(30,0,$m240$المادة 30$m240$,$m240$( 1 ) يرسل المدعى خلال الميعاد المتفق عليه بين الطرفين أو الذى تعينه هيئة التحكيم إلى المدعى عليه والى كل واحد من المحكمين بيانا مكتوبا بدعواه يشتمل على اسمه وعنوانه واسم المدعى عليه وعنوانه وشرح لوقائع الدعوى وتحديد للمسائل محل النزاع وطلباته وكل أمر آخر يوجب اتفاق الطرفين ذكره فى هذا البيان .
( 2 ) ويرسل المدعى عليه خلال الميعاد المتفق عليه بين الطرفين أو الذى تعينه هيئة التحكيم إلى المدعى وكل واحد من المحكمين مذكرة مكتوبة بدفاعه ردا على ما جاء ببيان الدعوى ، وله أن يضمن هذه المذكرة أية طلبات عارضة متصلة بموضوع النزاع أو أن يتمسك بحق ناشىء عنه بقصد الدفع بالمقاصة ، وله ذلك ولو فى مرحلة لاحقة من الإجراءات إذا رأت هيئة التحكيم أن الظروف تبرر التأخير .
( 3 ) يجوز لكل من الطرفين أن يرفق ببيان الدعوى أو بمذكرة الدفاع على حسب الأحوال ، صورا من الوثائق التى يستند إليها وأن يشير الى كل أو بعض الوثائق وأدلة الإثبات التى يعتزم تقديمها . ولا يخل هذا بحق هيئة التحكيم فى
أى مرحلة كانت عليها الدعوى فى طلب تقديم أصول المستندات أو الوثائق التى يستند إليها أى من طرفى الدعوى .$m240$,'208152d641fafe9c845de224bb753a4e'),
(31,0,$m240$المادة 31$m240$,$m240$ترسل صورة مما يقدمه أحد الطرفين الى هيئة التحكيم من مذكرات أو مستندات أو أوراق أخرى الى الطرف الآخر وكذلك ترسل إلى كل من الطرفين صورة من كل ما يقدم الى الهيئة المذكورة من تقارير الخبراء والمستندات وغيرها من الأدلة .$m240$,'df8399f3de148cd300bef0ad86b8b1f4'),
(32,0,$m240$المادة 32$m240$,$m240$لكل من طرفى التحكيم تعديل طلباته أو أوجه دفاعه أو استكمالها خلال إجراءات التحكيم ما لم تقرر هيئة التحكيم عدم قبول ذلك منعا من تعطيل الفصل فى النزاع .$m240$,'c2e44b947bfb352a3b88294eb6b24d78'),
(33,0,$m240$المادة 33$m240$,$m240$( 1 ) تعقد هيئة التحكيم جلسات مرافعة لتمكين كل من الطرفين من شرح موضوع الدعوى وعرض حججه وأدلته ، ولها الاكتفاء بتقديم المذكرات والوثائق المكتوبة ما لم يتفق الطرفان على غير ذلك .
( 2 ) ويجب إخطار طرفى التحكيم بمواعيد الجلسات والاجتماعات التى تقرر هيئة التحكيم عقدها قبل التاريخ الذى تعينه لذلك بوقت كاف تقدره هذه الهيئة حسب الظروف .
( 3 ) وتدون خلاصة وقائع كل جلسة تعقدها هيئة التحكيم فى محضر تسلم صورة منه الى كل من الطرفين ما لم يتفقا على غير ذلك .
( 4 ) ويكون سماع الشهود والخبراء بدون أداء يمين .$m240$,'83156badf83705946f479fb595fb01dc'),
(34,0,$m240$المادة 34$m240$,$m240$( 1 ) اذا لم يقدم المدعى دون عذر مقبول بيانا مكتوبا بدعواه وفقا للفقرة الأولى من المادة ( 30 ) وجب أن تأمر هيئة التحكيم بإنهاء إجراءات التحكيم ما لم يتفق الطرفان على غير ذلك .
( 2 ) واذا لم يقدم المدعى عليه مذكرة بدفاعه وفقا للفقرة الثانية من المادة ( 30 ) من هذا لقانون وجب أن تستمر هيئة التحكيم فى إجراءات التحكيم دون أن يعتبر ذلك بذاته إقرارا من المدعى عليه بدعوى المدعى ، ما لم يتفق الطرفان على غير ذلك .$m240$,'e04edcf3e8ffb5dd5c0e8615f272c055'),
(35,0,$m240$المادة 35$m240$,$m240$إذا تخلف أحد الطرفين عن حضور إحدى الجلسات أو عن تقديم ما طلب منه من مستندات جاز لهيئة التحكيم الاستمرار فى إجراءات التحكيم وإصدار حكم فى النزاع استنادا إلى عناصر الإثبات الموجودة أمامها .$m240$,'68ada345c451e7b4fdd0f8b554490aaa'),
(36,0,$m240$المادة 36$m240$,$m240$( 1 ) لهيئة التحكيم تعيين خبير أو أكثر لتقديم تقرير مكتوب
أو شفهى يثبت فى محضر الجلسة بشأن مسائل معينة تحددها . وترسل إلى كل من الطرفين صورة من قرارها بتحديد المهمة المسندة الى الخبير .
( 2 ) وعلى كل من الطرفين أن يقدم الى الخبير المعلومات المتعلقة بالنزاع وأن يمكنه من معاينة وفحص مايطلبه من وثائق أو بضائع أو أموال أخرى متعلقة بالنزاع ، وتفصل هيئة التحكيم فى كل نزاع يقوم بين الخبير وأحد الطرفين فى هذا الشأن .
( 3 ) وترسل هيئة التحكيم صورة من تقرير الخبير بمجرد إيداعه إلى كل من الطرفين مع إتاحة الفرصة له لإبداء رأيه فيه ، ولكل من الطرفين الحق فى الاطلاع على الوثائق التى استند اليها الخبير فى تقريره وفحصها .
( 4 ) ولهيئة التحكيم بعد تقديم تقرير الخبير أن تقرر من تلقاء نفسها أو بناء على طلب أحد طرفى التحكيم عقد جلسة لسماع أقوال الخبير مع إتاحة الفرصة للطرفين لسماعه ومناقشته بشأن ما ورد فى تقريره . ولكل من الطرفين أن يقدم فى هذه الجلسة خبيرا أو أكثر من طرفه لإبداء الرأى فى المسائل التى تناولها تقرير الخبير الذى عينته هيئة التحكيم ما لم يتفق طرفا التحكيم على غير ذلك .$m240$,'12ca3be20f8b9edf6f4c715c407bd710'),
(37,0,$m240$المادة 37$m240$,$m240$يختص رئيس المحكمة المشار اليها فى المادة ( 9 ) من هذا القانون بناء على طلب هيئة التحكيم بما يأتى :
( أ ) الحكم على من يتخلف من الشهود عن الحضور أو يمتنع عن الإجابة بالجزاءات المنصوص عليها فى المادتين 78 و 80 من قانون الإثبات فى المواد المدنية والتجارية .
( ب ) الأمر بالإنابة القضائية .$m240$,'6b5aa2d1bc4a220a28f9e8ae2080c63c'),
(38,0,$m240$المادة 38$m240$,$m240$ينقطع سير الخصومة أمام هيئة التحكيم فى الأحوال ووفقا للشروط المقررة لذلك فى المرافعات المدنية والتجارية ، ويترتب على انقطاع سير الخصومة الآثار المقررة فى القانون المذكور .$m240$,'b4d56947eecbdfa411572cecc70b5860'),
(39,0,$m240$المادة 39$m240$,$m240$( 1 ) تطبق هيئة التحكيم على موضوع النزاع القواعد التى
يتفق عليها الطرفان . واذا اتفقا على تطبيق قانون دولة معينة اتبعت القواعد الموضوعية فيه دون القواعد الخاصة بتنازع القوانين ما لم يتفق على غير ذلك .
( 2 ) واذا لم يتفق الطرفان على القواعد القانونية واجبة التطبيق على موضوع النزاع طبقت هيئة التحكيم القواعد الموضوعية فى القانون الذى ترى أنه الأكثر اتصالا بالنزاع .
( 3 ) يجب أن تراعى هيئة التحكيم عند الفصل فى موضوع النزاع شروط العقد محل النزاع والأعراف الجارية فى نوع المعاملة .
( 4 ) يجوز لهيئة التحكيم - اذا اتفق طرفا التحكيم صراحة على تفويضها بالصلح - أن تفصل فى موضوع النزاع على مقتضى قواعد العدالة والإنصاف دون التقيد بأحكام القانون .$m240$,'c68b406a9aec63d31af5f04a32a9a645'),
(40,0,$m240$المادة 40$m240$,$m240$يصدر حكم هيئة التحكيم المشكلة من أكثر من محكم واحد بأغلبية الآراء بعد مداولة تتم على الوجه الذى تحدده هيئة التحكيم ، ما لم يتفق طرفا التحكيم على غير ذلك .$m240$,'605e47f9ce922aed396311494ac329ff'),
(41,0,$m240$المادة 41$m240$,$m240$اذا اتفق الطرفان خلال إجراءات التحكيم على تسوية تنهى النزاع كان لهما أن يطلبا إثبات شروط التسوية أمام هيئة التحكيم ، التى يجب عليها فى هذه الحالة أن تصدر قرارا يتضمن شروط التسوية وينهى الإجراءات ، ويكون لهذا القرار ما لأحكام المحكمين من قوة بالنسبة للتنفيذ .$m240$,'c179db3cd24210a2896bbb9492881461'),
(42,0,$m240$المادة 42$m240$,$m240$يجوز أن تصدر هيئة التحكيم أحكاما وقتية أو فى جزء من الطلبات وذلك قبل إصدار الحكم المنهى للخصومة كلها .$m240$,'f46441464764db29333b1e1ff9ea4723'),
(43,0,$m240$المادة 43$m240$,$m240$( 1 ) يصدر حكم التحكيم كتابة ويوقعه المحكمون ، وفى حالة تشكيل هيئة التحكيم من أكثر من محكم واحد يكتفى بتوقيعات أغلبية المحكمين بشرط أن تثبت فى الحكم أسباب عدم توقيع الأقلية .
( 2 ) يجب أن يكون حكم التحكيم مسببا إلا إذا اتفق طرفا التحكيم على غير ذلك أو كان القانون الواجب التطبيق على إجراءات التحكيم لا يشترط ذكر أسباب الحكم .
( 3 ) يجب أن يشتمل حكم التحكيم على أسماء الخصوم وعناوينهم وأسماء المحكمين وعناوينهم وجنسياتهم وصفاتهم وصورة من اتفاق التحكيم وملخص لطلبات الخصوم وأقوالهم ومستنداتهم ومنطوق الحكم وتاريخ ومكان إصداره وأسبابه اذا كان ذكرها واجبا .$m240$,'e4e725d656400a1e69aa0d342513b274'),
(44,0,$m240$المادة 44$m240$,$m240$( 1 ) تسلم هيئة التحكيم الى كل من الطرفين صورة من حكم التحكيم موقعة من المحكمين الذين وافقوا عليه خلال ثلاثين يوما من تاريخ صدوره .
( 2 ) ولا يجوز نشر حكم التحكيم أو نشر أجزاء منه إلا بموافقة طرفى التحكيم .$m240$,'52fe49d0b72efa92973c63351b8dd285'),
(45,0,$m240$المادة 45$m240$,$m240$( 1 ) على هيئة التحكيم أصدار الحكم المنهى للخصومة كلها خلال الميعاد الذى اتفق عليه الطرفان . فإن لم يوجد اتفاق وجب أن يصدر الحكم خلال اثنى عشر شهرا من تاريخ بدء إجراءات التحكيم . وفى جميع الأحوال يجوز أن تقرر هيئة التحكيم مد الميعاد على إلا تزيد فترة المد على ستة أشهر ما لم يتفق الطرفان على مدة تزيد على ذلك .
( 2 ) واذا لم يصدر حكم التحكيم خلال الميعاد المشار اليه فى الفقرة السابقة جاز لأى من طرفى التحكيم أن يطلب من رئيس المحكمة المشار اليها فى المادة ( 9 ) من هذا القانون ، أن يصدر أمرا بتحديد ميعاد إضافى أو بإنهاء اجراءات التحكيم . ويكون لأى من الطرفين عندئذ رفع دعواه الى المحكمة المختصة أصلا بنظرها .$m240$,'5fb6abd0b79e4f1d6fc154ddc89a60fa'),
(46,0,$m240$المادة 46$m240$,$m240$اذا عرضت خلال إجراءات التحكيم مسألة تخرج عن ولاية هيئة التحكيم أو طعن بالتزوير فى ورقة قدمت لها أو اتخذت اجراءات جنائية عن تزويرها أو عن فعل جنائى أخر ، جاز لهيئة التحكيم الاستمرار فى نظر موضوع النزاع إذا رأت أن الفصل فى هذه المسألة أو فى تزوير الورقة أو فى الفعل الجنائى الآخر ليس لازما للفصل فى موضوع النزاع ، والا أوقفت الإجراءات حتى يصدر حكم نهائى فى هذا الشأن ، ويترتب على ذلك وقف سريان الميعاد المحدد لإصدار حكم التحكيم .$m240$,'c8e91072ce9553c84790049b88ff1194'),
(47,0,$m240$المادة 47$m240$,$m240$يجب على من صدر حكم التحكيم لصالحه إيداع أصل الحكم أو صورة موقعة منه باللغة التى صدر بها ، أو ترجمة باللغة العربية مصدقا عليها من جهة معتمدة اذا كان صادرا بلغة أجنبية ، وذلك فى قلم كتاب المحكمة المشار اليها فى المادة ( 9 ) من هذا القانون .
ويحرر كاتب المحكمة محضرا بهذا الإيداع ويجوز لكل من طرفى التحكيم طلب الحصول على صورة من هذا المحضر .$m240$,'40e83fb5a30e0c42dd978142ff5b5eaf'),
(48,0,$m240$المادة 48$m240$,$m240$( 1 ) تنتهى إجراءات التحكيم بصدور الحكم المنهى للخصومة
كلها أو بصدور أمر بإنهاء اجراءات التحكيم وفقا للفقرة الثانية من المادة ( 45 ) من هذا القانون . كما تنتهى أيضا بصدور قرار من هيئة التحكيم بإنهاء الاجراءات فى الأحوال الآتية :
( أ ) إذا اتفق الطرفان على إنهاء التحكيم .
( ب ) إذا ترك المدعى خصومة التحكيم ما لم تقرر هيئة التحكيم ، بناء على طلب المدعى عليه ، أن له مصلحة جدية فى استمرار الإجراءات حتى يحسم النزاع .
( ج ) إذا رأت هيئة التحكيم لأى سبب آخر عدم جدوى استمرار اجراءات التحكيم أو استحالته .
( 2 ) مع مراعاة أحكام المواد 49 و 50 و 51 من هذا القانون تنتهى مهمة هيئة التحكيم بانتهاء اجراءات التحكيم .$m240$,'251fe7428974cf7a586c7c83aefc4384'),
(49,0,$m240$المادة 49$m240$,$m240$( 1 ) يجوز لكل من طرفى التحكيم أن يطلب من هيئة التحكيم ، خلال الثلاثين يوما التالية لتسلمه حكم التحكيم ، تفسير ما وقع فى منطوقه من غموض . ويجب على طالب التفسير إعلان الطرف الآخر بهذا الطلب قبل تقديمه لهيئة التحكيم .
( 2 ) يصدر التفسير كتابة خلال الثلاثين يوما التالية لتاريخ تقديم طلب التفسير لهيئة التحكيم . ويجوز لهذه الهيئة مد هذا الميعاد ثلاثين يوما أخرى إذا رأت ضرورة لذلك .
( 3 ) ويعتبر الحكم الصادر بالتفسير متمما لحكم التحكيم الذى يفسره وتسرى عليه أحكامه .$m240$,'f329bc70ee14ff9d5c5040c2d2521398'),
(50,0,$m240$المادة 50$m240$,$m240$( 1 ) تتولى هيئة التحكيم تصحيح ما يقع فى حكمها من أخطاء مادية بحتة ، كتابية أو حسابية ، وذلك بقرار تصدره من تلقاء نفسها أو بناء على طلب أحد الخصوم . وتجرى هيئة التحكيم التصحيح من غير مرافعة خلال الثلاثين يوما التالية لتاريخ صدور الحكم أو إيداع طلب التصحيح بحسب الأحوال . ولها مد هذا الميعاد ثلاثين يوما أخرى اذا رأت ضرورة لذلك .
( 2 ) ويصدر قرار التصحيح كتابة من هيئة التحكيم ويعلن إلى الطرفين خلال ثلاثين يوما من تاريخ صدوره واذا تجاوزت هيئة التحكيم سلطتها فى التصحيح جاز التمسك ببطلان هذا القرار بدعوى بطلان تسرى عليها أحكام المادتين ( 53 ) ، ( 54 ) من هذا القانون .$m240$,'a48e9a37d0a140b301c4f71f9c57b2ca'),
(51,0,$m240$المادة 51$m240$,$m240$( 1 ) يجوز لكل من طرفى التحكيم ، ولو بعد انتهاء ميعاد التحكيم ، أن يطلب من هيئة التحكيم خلال الثلاثين يوما التالية لتسلمه حكم التحكيم إصدار حكم تحكيم إضافى فى طلبات قدمت خلال الاجراءات وأغفلها حكم التحكيم : ويجب إعلان هذا الطلب إلى الطرف الآخر قبل تقديمه .
( 2 ) وتصدر هيئة التحكيم حكمها خلال ستين يوما من تاريخ تقديم الطلب ويجوز لها مد هذا الميعاد ثلاثين يوما أخرى اذا رأت ضرورة لذلك .$m240$,'ac5ace089bb9108b0aea7c9536bcb1ca'),
(52,0,$m240$المادة 52$m240$,$m240$( 1 ) لا تقبل أحكام التحكيم التى تصدر طبقا لأحكام هذا القانون الطعن فيها بأى طريق من طرق الطعن المنصوص عليها فى قانون المرافعات المدنية والتجارية .
( 2 ) يجوز رفع دعوى بطلان حكم التحكيم وفقا للأحكام المبينة فى المادتين التاليتين .$m240$,'724826421959405955665b3c28efc402'),
(53,0,$m240$المادة 53$m240$,$m240$( 1 ) لا تقبل دعوى بطلان حكم التحكيم إلا فى الأحوال الآتية :
( أ ) إذا لم يوجد اتفاق تحكيم أو كان هذا الاتفاق باطلا أو قابلا للابطال أو سقط بانتهاء مدته .
( ب ) إذا كان أحد طرفى اتفاق التحكيم وقت إبرامه فاقد الأهلية أو ناقصها وفقا للقانون الذى يحكم أهليته .
( ج ) إذا تعذر على أحد طرفى التحكيم تقديم دفاعه بسبب عدم إعلانه إعلانا صحيحا بتعيين محكم أو بإجراءات التحكيم أو لأى سبب آخر خارج عن إرادته .
( د ) إذا استبعد حكم التحكيم تطبيق القانون الذى اتفق الأطراف على تطبيقه على موضوع النزاع .
( هـ ) إذا تم تشكيل هيئة التحكيم أو تعيين المحكمين على وجه مخالف للقانون أو لاتفاق الطرفين .
( و ) إذا فصل حكم التحكيم فى مسائل لا يشملها اتفاق التحكيم أو جاوز حدود هذا الاتفاق . ومع ذلك إذا أمكن فصل أجزاء الحكم الخاصة بالمسائل الخاضعة للتحكيم عن أجزائه الخاصة بالمسائل غير الخاضعة له فلا يقع البطلان إلا على الأجزاء الأخيرة وحدها .
( ز ) إذا وقع بطلان فى حكم التحكيم ، أو كانت إجراءات التحكيم باطلة بطلانا أثر فى الحكم .
( 2 ) وتقضى المحكمة التى تنظر دعوى البطلان من تلقاء نفسها ببطلان حكم التحكيم إذا تضمن ما يخالف النظام العام فى جمهورية مصر العربية .$m240$,'9865859cf97f806a3bd052521a1a3343'),
(54,0,$m240$المادة 54$m240$,$m240$( 1 ) ترفع دعوى بطلان حكم التحكيم خلال التسعين يوما التالية لتاريخ إعلان حكم التحكيم للمحكوم عليه . ولا يحول دون قبول دعوى البطلان نزول مدعى البطلان عن حقه فى رفعها قبل صدور حكم التحكيم .
( 2 ) تختص بدعوى البطلان فى التحكيم التجارى الدولى المحكمة المشار اليها فى المادة ( 9 ) من هذا القانون . وفى غير التحكيم التجارى الدولى يكون الاختصاص لمحكمة الدرجة الثانية التى تتبعها المحكمة المختصة أصلا بنظر النزاع .$m240$,'e4913cba2a0321f15c8723b6375f4dbf'),
(55,0,$m240$المادة 55$m240$,$m240$تحوز أحكام المحكمين الصادرة طبقا لهذا القانون حجية الأمر المقضى وتكون واجبة النفاذ بمراعاة الأحكام المنصوص عليها فى هذا القانون .$m240$,'4d216a5b848048b59e657957d4369b84'),
(56,0,$m240$المادة 56$m240$,$m240$يختص رئيس المحكمة المشار اليها فى المادة ( 9 ) من هذا القانون أو من يندبه من قضاتها بإصدار الأمر بتنفيذ حكم المحكمين ، ويقدم طلب تنفيذ الحكم مرفقا به ما يلى :
1 - أصل الحكم أو صورة موقعة منه .
2 - صورة من اتفاق التحكيم .
3 - ترجمة مصدق عليها من جهة معتمدة إلى اللغة العربية لحكم التحكيم إذا لم يكن صادرا بها .
4 - صورة من المحضر الدال على إيداع الحكم وفقا للمادة ( 47 ) من هذا القانون .$m240$,'bfe6eb282a1640151495ffc81574c350'),
(57,0,$m240$المادة 57$m240$,$m240$لا يترتب على رفع دعوى البطلان وقف تنفيذ حكم التحكيم ، ومع ذلك يجوز للمحكمة أن تأمر بوقف التنفيذ اذا طلب المدعى ذلك فى صحيفة الدعوى وكان الطلب مبنيا على أسباب جدية وعلى المحكمة الفصل فى طلب وقف التنفيذ خلال ستين يوما من تاريخ أول جلسة محددة لنظره ، وإذا أمرت بوقف التنفيذ جاز لها أن تأمر بتقديم كفالة أو ضمان مالى . وعليها إذا أمرت بوقف التنفيذ ، الفصل فى دعوى البطلان خلال ستة أشهر من تاريخ صدور هذا الأمر .$m240$,'b574e5bf0dd10d347dafd333385dc2a3'),
(58,0,$m240$المادة 58$m240$,$m240$( 1 ) لا يقبل طلب تنفيذ حكم التحكيم اذا لم يكن ميعاد رفع دعوى بطلان الحكم قد انقضى .
( 2 ) لا يجوز الأمر بتنفيذ حكم التحكيم وفقا لهذا القانون الا بعد التحقق مما يأتى :
( أ ) أنه لا يتعارض مع حكم سبق صدوره من المحاكم المصرية فى موضوع النزاع .
( ب ) أنه لا يتضمن ما يخالف النظام العام فى جمهورية مصر العربية .
( ج ) أنه قد تم إعلانه للمحكوم عليه إعلانا صحيحا .
( 3 ) ولا يجوز التظلم من الأمر الصادر بتنفيذ حكم التحكيم . أما الأمر الصادر برفض التنفيذ فيجوز التظلم منه إلى المحكمة المختصة وفقا لحكم المادة ( 9 ) من هذا القانون خلال ثلاثين يوما من تاريخ صدوره .$m240$,'1ec97de8546993d7e55bc8db60bcff12');

INSERT INTO m240_ver VALUES
(0,0,1,$m240$قانون رقم 27 لسنة 1994 بإصدار قانون فى شأن التحكيم فى المواد المدنية والتجارية
باسم الشعب رئيس الجمهورية قرر مجلس الشعب القانون الآتى نصه ، وقد أصدرناه :$m240$,'d25a93408effeda0016e02347c502ad4',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(1,-1,1,$m240$يعمل بأحكام القانون المرافق على كل تحكيم قائم وقت نفاذه أو يبدأ بعد نفاذه ولو استند إلى اتفاق تحكيم سبق إبرامه قبل نفاذ هذا القانون .$m240$,'eb64c307e39c676419e69f3337a31fb6',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(2,-1,1,$m240$يصدر وزير العدل القرارات اللازمة لتنفيذ أحكام هذا القانون . ويضع قوائم المحكمين الذين يجرى الاختيار من بينهم وفقا لحكم المادة ( 17 ) من هذا القانون .$m240$,'1ed7312029bd0b68926ef23bd31d15b6',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(3,-1,1,$m240$تلغى المواد من 501 إلى 513 من القانون رقم 13 لسنة 1968 بإصدار قانون المرافعات المدنية والتجارية ، كما يلغى أى حكم مخالف لأحكام هذا القانون .$m240$,'5d125ddb86279649e35693508f70c44f',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(4,-1,1,$m240$ينشر هذا القانون فى الجريدة الرسمية ، ويعمل به بعد شهر من اليوم التالى لتاريخ نشره .
يبصم هذا القانون بخاتم الدولة ، وينفذ كقانون من قوانينها .
صدر برئاسة الجمهورية فى 7 ذى القعدة سنة 1414 هـ الموافق 18 أبريل سنة 1994 م
حسنى مبارك$m240$,'d2c963435ba518c82145d9a2d753ecdb',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(1,0,1,$m240$مع عدم الإخلال بأحكام الاتفاقيات الدولية المعمول بها فى جمهورية مصر العربية تسرى أحكام هذا القانون على كل تحكيم بين أطراف من أشخاص القانون العام أو القانون الخاص أيا كانت طبيعة العلاقة القانونية التى يدور حولها النزاع اذا كان هذا التحكيم يجرى فى مصر ، أو كان تحكيما تجاريا دوليا يجرى فى الخارج واتفق أطرافه على اخضاعه لأحكام هذا القانون .$m240$,'b4cb799a088c5a94598460264c24e522',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(2,0,1,$m240$يكون التحكيم تجاريا فى حكم هذا القانون إذا نشأ النزاع حول علاقة قانونية ذات طابع اقتصادى ، عقدية كانت أو غير عقدية ، ويشمل ذلك على سبيل المثال توريد السلع أو الخدمات والوكالات التجارية وعقود التشييد والخبرة الهندسية أو الفنية ومنح التراخيص الصناعية والسياحية وغيرها ونقل التكنولوجيا والاستثمار وعقود التنمية وعمليات البنوك والتأمين والنقل وعمليات تنقيب واستخراج الثروات الطبيعية وتوريد الطاقة ومد أنابيب الغاز أو النفط وشق الطرق والانفاق واستصلاح الأراضى الزراعية وحماية البيئة وإقامة المفاعلات النووية .$m240$,'bc07e36b7a3d4df4f6f90886ad2270c1',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(3,0,1,$m240$يكون التحكيم دوليا فى حكم هذا القانون إذا كان موضوعه نزاعا يتعلق بالتجارة الدولية وذلك فى الأحوال الآتية :
أولا : اذا كان المركز الرئيسى لأعمال كل من طرفى التحكيم يقع فى دولتين مختلفتين وقت إبرام اتفاق التحكيم . فإذا كان لأحد الطرفين عدة مراكز للأعمال فالعبرة بالمركز الأكثر ارتباطا بموضوع اتفاق التحكيم . وإذا لم يكن لأحد طرفى التحكيم مركز أعمال فالعبرة بمحل إقامته المعتاد .
ثانيا : إذا اتفق طرفا التحكيم على اللجوء إلى منظمة تحكيم دائمة أو مركز للتحكيم يوجد مقره داخل جمهورية مصر العربية أو خارجها .
ثالثا : إذا كان موضوع النزاع الذى يشمله اتفاق التحكيم يرتبط بأكثر من دولة واحدة .
رابعا : اذا كان المركز الرئيسى لأعمال كل من طرفى التحكيم يقع فى نفس الدولة وقت إبرام اتفاق التحكيم وكان أحد الأماكن التالية واقعا خارج هذه الدولة :
( أ ) مكان إجراء التحكيم كما عينه اتفاق التحكيم أو أشار إلى كيفية تعيينه .
( ب ) مكان تنفيذ جانب جوهرى من الالتزامات الناشئة عن العلاقة التجارية بين الطرفين .
( جـ ) المكان الأكثر ارتباطا بموضوع النزاع .$m240$,'6fb32cfdaf971c36e03c7a660055d07f',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(4,0,1,$m240$( 1 ) ينصرف لفظ : « التحكيم » فى حكم هذا القانون إلى التحكيم الذى يتفق عليه طرفا النزاع بارادتهما الحرة سواء كانت الجهة التى تتولى إجراءات التحكيم ، بمقتضى اتفاق الطرفين ، منظمة أو مركز دائم للتحكيم أو لم يكن كذلك .
( 2 ) وتنصرف عبارة : « هيئة التحكيم » إلى الهيئة المشكلة من محكم واحد أو أكثر للفصل فى النزاع المحال إلى التحكيم . أما لفظ « المحكمة » فينصرف إلى المحكمة التابعة للنظام القضائى فى الدولة .
( 3 ) وتنصرف عبارة « طرفى التحكيم » فى هذا القانون إلى أطراف التحكيم ولو تعددوا .$m240$,'c1b283fd9028c0ff48967069859aedf9',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(5,0,1,$m240$فى الأحوال التى يجيز فيها هذا القانون لطرفى التحكيم اختيار الإجراء الواجب الاتباع فى مسألة معينة تضمن ذلك حقهما فى الترخيص للغير فى اختيار هذا الإجراء ، ويعتبر من الغير فى هذا الشأن كل منظمة أو مركز للتحكيم فى جمهورية مصر العربية أو فى خارجها .$m240$,'ab2aca9bd8d1787f445a60b8fb9f95a0',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(6,0,1,$m240$إذا اتفق طرفا التحكيم على إخضاع العلاقة القانونية بينهما لأحكام عقد نموذجى أو اتفاقية دولية أو أية وثيقة أخرى . وجب العمل بأحكام هذه الوثيقة بما تشمله من أحكام خاصة بالتحكيم .$m240$,'7e7c781fb0db48e3cc8bfa672c49a39d',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(7,0,1,$m240$( 1 ) ما لم يوجد اتفاق خاص بين طرفى التحكيم ، يتم تسليم أى رسالة أو إعلان إلى المرسل اليه شخصيا أو فى مقر عمله أو فى محل إقامته المعتاد أو فى عنوانه البريدى المعروف للطرفين أو المحدد فى مشارطة التحكيم أو فى الوثيقة المنظمة للعلاقة التى يتناولها التحكيم .
( 2 ) وإذا تعذر معرفة أحد هذين العنوانين بعد إجراء التحريات اللازمة ، يعتبر التسليم قد تم إذا كان الإعلان بكتاب مسجل إلى آخر مقر عمل أو محل إقامة معتاد أو عنوان بريدى معروف للمرسل إليه .
( 3 ) لا تسرى أحكام هذه المادة على الإعلانات القضائية أمام المحاكم .$m240$,'f64bf60933b176600ca850b84be29c40',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(8,0,1,$m240$إذا استمر أحد طرفى النزاع فى إجراءات التحكيم مع علمه بوقوع مخالفة لشرط فى اتفاق التحكيم أو لحكم من أحكام هذا القانون مما يجوز الاتفاق على مخالفته ولم يقدم اعتراضا على هذه المخالفة فى الميعاد المتفق عليه أو فى وقت معقول عند عدم الاتفاق ، اعتبر ذلك نزولا منه عن حقه فى الاعتراض .$m240$,'a64fef5b3de119023c3f0861219dfa4b',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(9,0,1,$m240$( 1 ) يكون الاختصاص بنظر مسائل التحكيم التى يحيلها هذا القانون إلى القضاء المصرى للمحكمة المختصة أصلا بنظر النزاع . أما إذا كان التحكيم تجاريا دوليا ، سواء جرى فى مصر أو فى الخارج ، فيكون الاختصاص لمحكمة استئناف القاهرة ما لم يتفق الطرفان على اختصاص محكمة استئناف أخرى فى مصر .
( 2 ) وتظل المحكمة التى ينعقد لها الاختصاص وفقا للفقرة السابقة دون غيرها صاحبة الاختصاص حتى انتهاء جميع إجراءات التحكيم .$m240$,'7c8a1a8ddf6328994e2becfc02e0077d',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(10,0,1,$m240$( 1 ) اتفاق التحكيم هو اتفاق الطرفين على الالتجاء إلى التحكيم لتسوية كل أو بعض المنازعات التى نشأت أو يمكن أن تنشأ بينهما بمناسبة علاقة قانونية معينة عقدية كانت أو غير عقدية .
( 2 ) يجوز أن يكون اتفاق التحكيم سابقا على قيام النزاع سواء قام مستقلا بذاته أو ورد فى عقد معين بشأن كل أو بعض المنازعات التى قد تنشأ بين الطرفين ، وفى هذه الحالة يجب أن يحدد موضوع النزاع فى بيان الدعوى المشار اليه فى الفقرة الأولى من المادة ( 30 ) من هذا القانون ، كما يجوز أن يتم اتفاق التحكيم بعد قيام النزاع ولو كانت قد أقيمت فى شأنه دعوى أمام جهة قضائية ، وفى هذه الحالة يجب أن يحدد الاتفاق المسائل التى يشملها التحكيم وإلا كان الاتفاق باطلا .
( 3 ) ويعتبر اتفاقا على التحكيم كل إحالة ترد فى العقد إلى وثيقة تتضمن شرط تحكيم إذا كانت الإحالة واضحة فى اعتبار هذا الشرط جزءا من العقد .$m240$,'02bf10f3f0b22b385da0edb29a41c63c',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(11,0,1,$m240$لا يجوز الاتفاق على التحكيم إلا للشخص الطبيعى أو الاعتبارى الذى يملك التصرف فى حقوقه ، ولا يجوز التحكيم فى المسائل التى لا يجوز فيها الصلح .$m240$,'0873b26e950908955780cc619e4fb8f8',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(12,0,1,$m240$يجب أن يكون اتفاق التحكيم مكتوبا وإلا كان باطلا . ويكون اتفاق التحكيم مكتوبا إذا تضمنه محرر وقعه الطرفان أو إذا تضمنه ما تبادله الطرفان من رسائل أو برقيات أو غيرها من وسائل الاتصال المكتوبة .$m240$,'b459c5f79a06a0db318cb59236fb20f4',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(13,0,1,$m240$( 1 ) يجب على المحكمة التى يرفع إليها نزاع يوجد بشأنه اتفاق تحكيم أن تحكم بعدم قبول الدعوى إذا دفع المدعى عليه بذلك قبل إبدائه أى طلب أو دفاع فى الدعوى .
( 2 ) ولا يحول رفع الدعوى المشار إليها فى الفقرة السابقة دون البدء فى إجراءات التحكيم أو الاستمرار فيها أو إصدار حكم التحكيم .$m240$,'a11ba22abbb1f31a057f368b1b6f6400',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(14,0,1,$m240$يجوز للمحكمة المشار اليها فى المادة ( 9 ) من هذا القانون أن تأمر ، بناء على طلب أحد طرفى التحكيم ، باتخاذ تدابير مؤقتة أو تحفظية سواء قبل البدء فى إجراءات التحكيم أو أثناء سيرها .$m240$,'5dfc2aca404d8bed9bdce28608f2852b',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(15,0,1,$m240$( 1 ) تشكل هيئة التحكيم باتفاق الطرفين من محكم واحد أو أكثر ، فإذا لم يتفقا على عدد المحكمين كان العدد ثلاثة .
( 2 ) إذا تعدد المحكمون وجب أن يكون عددهم وترا ، وإلا كان التحكيم باطلا .$m240$,'b5ae9b5bc7c804c2b82cee102d84bcbc',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(16,0,1,$m240$( 1 ) لا يجوز أن يكون المحكم قاصرا أو محجورا عليه أو محروما من حقوقه المدنية بسبب الحكم عليه فى جناية أو جنحة مخلة بالشرف أو بسبب شهر إفلاسه ما لم يرد إليه اعتباره .
( 2 ) لا يشترط أن يكون المحكم من جنس أو جنسية معينة إلا إذا اتفق طرفا التحكيم أو نص القانون على غير ذلك .
( 3 ) يكون قبول المحكم القيام بمهمته كتابة ، ويجب عليه أن يفصح عند قبوله عن أية ظروف من شأنها إثارة شكوك حول استقلاله أو حيدته .$m240$,'6ae1bc97959d0b2f699e1bc21366a7cf',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(17,0,1,$m240$( 1 ) لطرفى التحكيم الاتفاق على اختيار المحكمين وعلى كيفية ووقت اختيارهم فإذا لم يتفقا اتبع ما يأتى :
( أ ) إذا كانت هيئة التحكيم مشكلة من محكم واحد تولت المحكمة المشار إليها فى المادة ( 9 ) من هذا القانون اختياره بناء على طلب أحد الطرفين .
( ب ) فإذا كانت هيئة التحكيم مشكلة من ثلاثة محكمين اختار كل طرف محكما ثم يتفق المحكمان على اختيار المحكم الثالث ، فإذا لم يعين أحد الطرفين محكمه خلال الثلاثين يوما التالية لتسلمه طلبا بذلك من الطرف الآخر ، أو إذا لم يتفق المحكمان المعينان على اختيار المحكم الثالث خلال الثلاثين يوما التالية لتاريخ تعيين آخرهما ، تولت المحكمة المشار إليها فى المادة ( 9 ) من هذا القانون اختياره بناء على طلب أحد الطرفين . ويكون للمحكم الذى اختاره المحكمان المعينان أو الذى اختارته المحكمة رئاسة هيئة التحكيم ، وتسرى هذه الأحكام فى حالة تشكيل هيئة التحكيم من أكثر من ثلاثة محكمين .
( 2 ) وإذا خالف أحد الطرفين إجراءات اختيار المحكمين التى اتفقا عليها ، أو لم يتفق المحكمان المعينان على أمر مما يلزم اتفاقهما عليه ، أو إذا تخلف الغير عن أداء ما عهد به إليه فى هذا الشأن ، تولت المحكمة المشار إليها فى المادة ( 9 ) من هذا القانون بناء على طلب أحد الطرفين ، القيام بالإجراء أو بالعمل المطلوب ما لم ينص فى الاتفاق على كيفية أخرى لإتمام هذا الإجراء أو العمل .
( 3 ) وتراعى المحكمة فى المحكم الذى تختاره الشروط التى يتطلبها هذا القانون وتلك التى اتفق عليها الطرفان ، وتصدر قرارها باختيار المحكم على وجه السرعة ، ومع عدم الإخلال بأحكام المادتين 18 و 19 من هذا القانون لايقبل هذا القرار الطعن فيه بأى طريق من طرق الطعن .$m240$,'39959964695c06e4c8224d0fd3631177',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(18,0,1,$m240$( 1 ) لا يجوز رد المحكم إلا إذا قامت ظروف تثير شكوكا جدية حول حيدته أو استقلاله .
( 2 ) ولا يجوز لأى من طرفى التحكيم رد المحكم الذى عينه أو اشترك فى تعيينه إلا لسبب تبينه بعد أن تم هذا التعيين .$m240$,'07395fcaef51a8115d6a8dd462ef883a',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(19,0,1,$m240$( 1 ) يقدم طلب الرد كتابة إلى هيئة التحكيم مبينا فيه أسباب الرد خلال خمسة عشر يوما من تاريخ علم طالب الرد بتشكيل هذه الهيئة أو بالظروف المبررة للرد ، فإذا لم يتنح المحكم المطلوب رده فصلت هيئة التحكيم فى الطلب .
( 2 ) ولا يقبل الرد ممن سبق له تقديم طلب برد المحكم نفسه فى ذات التحكيم .
( 3 ) لطالب الرد أن يطعن فى الحكم برفض طلبه خلال ثلاثين يوما من تاريخ إعلانه به أمام المحكمة المشار اليها فى المادة ( 9 ) من هذا القانون ، ويكون حكمها غير قابل للطعن بأى طريق .
( 4 ) لا يترتب على تقديم طلب الرد أو على الطعن فى حكم التحكيم الصادر برفضه وقف إجراءات التحكيم وإذا حكم برد المحكم ؛ سواء من هيئة التحكيم أو من المحكمة عند نظر الطعن ، ترتب على ذلك اعتبار ما يكون قد تم من إجراءات التحكيم ، بما فى ذلك حكم المحكمين ، كأن لم يكن .$m240$,'6a73c4fb2bd0d6373746db45dc68f543',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(20,0,1,$m240$إذا تعذر على المحكم أداء مهمته أو لم يباشرها أو انقطع عن أدائها بما يؤدى إلى تأخير لا مبرر له فى إجراءات التحكيم ولم يتنح ولم يتفق الطرفان على عزله ، جاز للمحكمة المشار إليها فى المادة ( 9 ) من هذا القانون الأمر بإنهاء مهمته بناء على طلب أى من الطرفين .$m240$,'f0760d25da80b4ab479841d6bac7d462',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(21,0,1,$m240$إذا انتهت مهمة المحكم بالحكم برده أو عزله أو تنحيه أو بأى سبب آخر ، وجب تعيين بديل له طبقا للإجراءات التى تتبع فى اختيار المحكم الذى انتهت مهمته .$m240$,'ebdc286565f54727792f119725fbd7a5',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(22,0,1,$m240$( 1 ) تفصل هيئة التحكيم فى الدفوع المتعلقة بعدم اختصاصها بما فى ذلك الدفوع المبنية على عدم وجود اتفاق تحكيم أو سقوطه أو بطلانه أو عدم شموله لموضوع النزاع .
( 2 ) يجب التمسك بهذه الدفوع فى ميعاد لا يجاوز ميعاد تقديم دفاع المدعى عليه المشار إليه فى الفقرة الثانية من المادة ( 30 ) من هذا القانون ولا يترتب على قيام أحد طرفى التحكيم بتعيين محكم أو الاشتراك فى تعيينه سقوط حقه فى تقديم أى من هذه الدفوع . أما الدفع بعدم شمول اتفاق التحكيم لما يثيره الطرف الآخر من مسائل أثناء نظر النزاع فيجب التمسك به فورا
وإلا سقط الحق فيه . ويجوز ، فى جميع الأحوال - أن تقبل هيئة التحكيم الدفع المتأخر إذا رأت أن التأخير كان لسبب مقبول .
( 3 ) تفصل هيئة التحكيم فى الدفوع المشار إليها فى الفقرة الأولى من هذه المادة قبل الفصل فى الموضوع أو أن تضمها إلى الموضوع لتفصل فيهما معا . فإذا قضت برفض الدفع ، فلا يجوز التمسك به إلا بطريق رفع دعوى بطلان حكم التحكيم المنهى للخصومة كلها وفقا للمادة ( 53 ) من هذا القانون .$m240$,'085d6780237f1d19e7d997d65444dd5f',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(23,0,1,$m240$يعتبر شرط التحكيم اتفاقا مستقلا عن شروط العقد الأخرى . ولا يترتب على بطلان العقد أو فسخه أو إنهائه أى أثر على شرط التحكيم الذى يتضمنه ، إذا كان هذا الشرط صحيحا فى ذاته .$m240$,'ae3745d996c1fdda53aafb7b0f3bc500',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(24,0,1,$m240$( 1 ) يجوز لطرفى التحكيم الاتفاق على أن يكون لهيئة التحكيم ، بناء على طلب أحدهما ، أن تأمر أيا منهما باتخاذ ما تراه من تدابير مؤقتة أو تحفظية تقتضيها طبيعة النزاع ، وأن تطلب تقديم ضمان كاف لتغطية نفقات التدبير الذى تأمر به .
( 2 ) وإذا تخلف من صدر إليه الأمر عن تنفيذه ، جاز لهيئة التحكيم ، بناء على طلب الطرف الآخر ، أن تأذن لهذا الطرف فى اتخاذ الإجراءات اللازمة لتنفيذه ، وذلك دون إخلال بحق هذا الطرف فى أن يطلب من رئيس المحكمة المشار إليها فى المادة ( 9 ) من هذا القانون الأمر بالتنفيذ .$m240$,'106d4b993c1f7179fe174f11a5d8ec9f',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(25,0,1,$m240$لطرفى التحكيم الاتفاق على الإجراءات التى تتبعها هيئة التحكيم بما فى ذلك حقهما فى إخضاع هذه الإجراءات للقواعد النافذة فى أى منظمة أو مركز تحكيم فى جمهورية مصر العربية أو خارجها فاذا لم يوجد مثل هذا الاتفاق كان لهيئة التحكيم ، مع مراعاه أحكام هذا القانون ، أن تختار إجراءات التحكيم التى تراها مناسبة .$m240$,'ecb22301206e572bdc5d921a69c77914',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(26,0,1,$m240$يعامل طرفا التحكيم على قدم المساواة وتهيأ لكل منهما فرصة متكافئة وكاملة لعرض دعواه .$m240$,'50e87ee91e82bf83de366ee6641ab1e5',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(27,0,1,$m240$تبدأ إجراءات التحكيم من اليوم الذى يتسلم فيه المدعى عليه طلب التحكيم من المدعى ، ما لم يتفق الطرفان على موعد آخر .$m240$,'26a0023b4f6f317752ab87488ee892c7',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(28,0,1,$m240$لطرفى التحكيم الاتفاق على مكان التحكيم فى مصر أو خارجها . فإذا لم يوجد اتفاق عينت هيئة التحكيم مكان التحكيم مع مراعاة ظروف الدعوى وملاءمة المكان لأطرافها . ولا يخل ذلك بسلطة هيئة التحكيم فى أن تجتمع فى أى مكان تراه مناسبا للقيام بإجراء من إجراءات التحكيم كسماع أطراف النزاع أو الشهود أو الخبراء أو الاطلاع على مستندات أو معاينة بضاعة أو أموال أو إجراء مداولة بين أعضائها أو غير ذلك .$m240$,'910ea4b036e580e8ecd2a4cfef3bd7c6',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(29,0,1,$m240$( 1 ) يجرى التحكيم باللغة العربية ما لم يتفق الطرفان أو تحدد هيئة التحكيم لغة أو لغات أخرى . ويسرى حكم الاتفاق أو القرار على لغة البيانات والمذكرات المكتوبة وعلى المرافعات الشفهية وكذلك على كل قرار تتخذه هذه الهيئة أو رسالة توجهها أو حكم تصدره مالم ينص اتفاق الطرفين أو قرار هيئة التحكيم على غير ذلك .
( 2 ) ولهيئة التحكيم أن تقرر أن يرفق بكل أو بعض الوثائق المكتوبة التى تقدم فى الدعوى ترجمة الى اللغة أو اللغات المستعملة فى التحكيم . وفى حالة تعدد هذه اللغات يجوز قصر الترجمة على بعضها .$m240$,'f60ffa05c3fd7ab639b9676ba622e6c5',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(30,0,1,$m240$( 1 ) يرسل المدعى خلال الميعاد المتفق عليه بين الطرفين أو الذى تعينه هيئة التحكيم إلى المدعى عليه والى كل واحد من المحكمين بيانا مكتوبا بدعواه يشتمل على اسمه وعنوانه واسم المدعى عليه وعنوانه وشرح لوقائع الدعوى وتحديد للمسائل محل النزاع وطلباته وكل أمر آخر يوجب اتفاق الطرفين ذكره فى هذا البيان .
( 2 ) ويرسل المدعى عليه خلال الميعاد المتفق عليه بين الطرفين أو الذى تعينه هيئة التحكيم إلى المدعى وكل واحد من المحكمين مذكرة مكتوبة بدفاعه ردا على ما جاء ببيان الدعوى ، وله أن يضمن هذه المذكرة أية طلبات عارضة متصلة بموضوع النزاع أو أن يتمسك بحق ناشىء عنه بقصد الدفع بالمقاصة ، وله ذلك ولو فى مرحلة لاحقة من الإجراءات إذا رأت هيئة التحكيم أن الظروف تبرر التأخير .
( 3 ) يجوز لكل من الطرفين أن يرفق ببيان الدعوى أو بمذكرة الدفاع على حسب الأحوال ، صورا من الوثائق التى يستند إليها وأن يشير الى كل أو بعض الوثائق وأدلة الإثبات التى يعتزم تقديمها . ولا يخل هذا بحق هيئة التحكيم فى
أى مرحلة كانت عليها الدعوى فى طلب تقديم أصول المستندات أو الوثائق التى يستند إليها أى من طرفى الدعوى .$m240$,'208152d641fafe9c845de224bb753a4e',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(31,0,1,$m240$ترسل صورة مما يقدمه أحد الطرفين الى هيئة التحكيم من مذكرات أو مستندات أو أوراق أخرى الى الطرف الآخر وكذلك ترسل إلى كل من الطرفين صورة من كل ما يقدم الى الهيئة المذكورة من تقارير الخبراء والمستندات وغيرها من الأدلة .$m240$,'df8399f3de148cd300bef0ad86b8b1f4',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(32,0,1,$m240$لكل من طرفى التحكيم تعديل طلباته أو أوجه دفاعه أو استكمالها خلال إجراءات التحكيم ما لم تقرر هيئة التحكيم عدم قبول ذلك منعا من تعطيل الفصل فى النزاع .$m240$,'c2e44b947bfb352a3b88294eb6b24d78',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(33,0,1,$m240$( 1 ) تعقد هيئة التحكيم جلسات مرافعة لتمكين كل من الطرفين من شرح موضوع الدعوى وعرض حججه وأدلته ، ولها الاكتفاء بتقديم المذكرات والوثائق المكتوبة ما لم يتفق الطرفان على غير ذلك .
( 2 ) ويجب إخطار طرفى التحكيم بمواعيد الجلسات والاجتماعات التى تقرر هيئة التحكيم عقدها قبل التاريخ الذى تعينه لذلك بوقت كاف تقدره هذه الهيئة حسب الظروف .
( 3 ) وتدون خلاصة وقائع كل جلسة تعقدها هيئة التحكيم فى محضر تسلم صورة منه الى كل من الطرفين ما لم يتفقا على غير ذلك .
( 4 ) ويكون سماع الشهود والخبراء بدون أداء يمين .$m240$,'83156badf83705946f479fb595fb01dc',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(34,0,1,$m240$( 1 ) اذا لم يقدم المدعى دون عذر مقبول بيانا مكتوبا بدعواه وفقا للفقرة الأولى من المادة ( 30 ) وجب أن تأمر هيئة التحكيم بإنهاء إجراءات التحكيم ما لم يتفق الطرفان على غير ذلك .
( 2 ) واذا لم يقدم المدعى عليه مذكرة بدفاعه وفقا للفقرة الثانية من المادة ( 30 ) من هذا لقانون وجب أن تستمر هيئة التحكيم فى إجراءات التحكيم دون أن يعتبر ذلك بذاته إقرارا من المدعى عليه بدعوى المدعى ، ما لم يتفق الطرفان على غير ذلك .$m240$,'e04edcf3e8ffb5dd5c0e8615f272c055',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(35,0,1,$m240$إذا تخلف أحد الطرفين عن حضور إحدى الجلسات أو عن تقديم ما طلب منه من مستندات جاز لهيئة التحكيم الاستمرار فى إجراءات التحكيم وإصدار حكم فى النزاع استنادا إلى عناصر الإثبات الموجودة أمامها .$m240$,'68ada345c451e7b4fdd0f8b554490aaa',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(36,0,1,$m240$( 1 ) لهيئة التحكيم تعيين خبير أو أكثر لتقديم تقرير مكتوب
أو شفهى يثبت فى محضر الجلسة بشأن مسائل معينة تحددها . وترسل إلى كل من الطرفين صورة من قرارها بتحديد المهمة المسندة الى الخبير .
( 2 ) وعلى كل من الطرفين أن يقدم الى الخبير المعلومات المتعلقة بالنزاع وأن يمكنه من معاينة وفحص مايطلبه من وثائق أو بضائع أو أموال أخرى متعلقة بالنزاع ، وتفصل هيئة التحكيم فى كل نزاع يقوم بين الخبير وأحد الطرفين فى هذا الشأن .
( 3 ) وترسل هيئة التحكيم صورة من تقرير الخبير بمجرد إيداعه إلى كل من الطرفين مع إتاحة الفرصة له لإبداء رأيه فيه ، ولكل من الطرفين الحق فى الاطلاع على الوثائق التى استند اليها الخبير فى تقريره وفحصها .
( 4 ) ولهيئة التحكيم بعد تقديم تقرير الخبير أن تقرر من تلقاء نفسها أو بناء على طلب أحد طرفى التحكيم عقد جلسة لسماع أقوال الخبير مع إتاحة الفرصة للطرفين لسماعه ومناقشته بشأن ما ورد فى تقريره . ولكل من الطرفين أن يقدم فى هذه الجلسة خبيرا أو أكثر من طرفه لإبداء الرأى فى المسائل التى تناولها تقرير الخبير الذى عينته هيئة التحكيم ما لم يتفق طرفا التحكيم على غير ذلك .$m240$,'12ca3be20f8b9edf6f4c715c407bd710',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(37,0,1,$m240$يختص رئيس المحكمة المشار اليها فى المادة ( 9 ) من هذا القانون بناء على طلب هيئة التحكيم بما يأتى :
( أ ) الحكم على من يتخلف من الشهود عن الحضور أو يمتنع عن الإجابة بالجزاءات المنصوص عليها فى المادتين 78 و 80 من قانون الإثبات فى المواد المدنية والتجارية .
( ب ) الأمر بالإنابة القضائية .$m240$,'6b5aa2d1bc4a220a28f9e8ae2080c63c',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(38,0,1,$m240$ينقطع سير الخصومة أمام هيئة التحكيم فى الأحوال ووفقا للشروط المقررة لذلك فى المرافعات المدنية والتجارية ، ويترتب على انقطاع سير الخصومة الآثار المقررة فى القانون المذكور .$m240$,'b4d56947eecbdfa411572cecc70b5860',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(39,0,1,$m240$( 1 ) تطبق هيئة التحكيم على موضوع النزاع القواعد التى
يتفق عليها الطرفان . واذا اتفقا على تطبيق قانون دولة معينة اتبعت القواعد الموضوعية فيه دون القواعد الخاصة بتنازع القوانين ما لم يتفق على غير ذلك .
( 2 ) واذا لم يتفق الطرفان على القواعد القانونية واجبة التطبيق على موضوع النزاع طبقت هيئة التحكيم القواعد الموضوعية فى القانون الذى ترى أنه الأكثر اتصالا بالنزاع .
( 3 ) يجب أن تراعى هيئة التحكيم عند الفصل فى موضوع النزاع شروط العقد محل النزاع والأعراف الجارية فى نوع المعاملة .
( 4 ) يجوز لهيئة التحكيم - اذا اتفق طرفا التحكيم صراحة على تفويضها بالصلح - أن تفصل فى موضوع النزاع على مقتضى قواعد العدالة والإنصاف دون التقيد بأحكام القانون .$m240$,'c68b406a9aec63d31af5f04a32a9a645',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(40,0,1,$m240$يصدر حكم هيئة التحكيم المشكلة من أكثر من محكم واحد بأغلبية الآراء بعد مداولة تتم على الوجه الذى تحدده هيئة التحكيم ، ما لم يتفق طرفا التحكيم على غير ذلك .$m240$,'605e47f9ce922aed396311494ac329ff',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(41,0,1,$m240$اذا اتفق الطرفان خلال إجراءات التحكيم على تسوية تنهى النزاع كان لهما أن يطلبا إثبات شروط التسوية أمام هيئة التحكيم ، التى يجب عليها فى هذه الحالة أن تصدر قرارا يتضمن شروط التسوية وينهى الإجراءات ، ويكون لهذا القرار ما لأحكام المحكمين من قوة بالنسبة للتنفيذ .$m240$,'c179db3cd24210a2896bbb9492881461',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(42,0,1,$m240$يجوز أن تصدر هيئة التحكيم أحكاما وقتية أو فى جزء من الطلبات وذلك قبل إصدار الحكم المنهى للخصومة كلها .$m240$,'f46441464764db29333b1e1ff9ea4723',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(43,0,1,$m240$( 1 ) يصدر حكم التحكيم كتابة ويوقعه المحكمون ، وفى حالة تشكيل هيئة التحكيم من أكثر من محكم واحد يكتفى بتوقيعات أغلبية المحكمين بشرط أن تثبت فى الحكم أسباب عدم توقيع الأقلية .
( 2 ) يجب أن يكون حكم التحكيم مسببا إلا إذا اتفق طرفا التحكيم على غير ذلك أو كان القانون الواجب التطبيق على إجراءات التحكيم لا يشترط ذكر أسباب الحكم .
( 3 ) يجب أن يشتمل حكم التحكيم على أسماء الخصوم وعناوينهم وأسماء المحكمين وعناوينهم وجنسياتهم وصفاتهم وصورة من اتفاق التحكيم وملخص لطلبات الخصوم وأقوالهم ومستنداتهم ومنطوق الحكم وتاريخ ومكان إصداره وأسبابه اذا كان ذكرها واجبا .$m240$,'e4e725d656400a1e69aa0d342513b274',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(44,0,1,$m240$( 1 ) تسلم هيئة التحكيم الى كل من الطرفين صورة من حكم التحكيم موقعة من المحكمين الذين وافقوا عليه خلال ثلاثين يوما من تاريخ صدوره .
( 2 ) ولا يجوز نشر حكم التحكيم أو نشر أجزاء منه إلا بموافقة طرفى التحكيم .$m240$,'52fe49d0b72efa92973c63351b8dd285',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(45,0,1,$m240$( 1 ) على هيئة التحكيم أصدار الحكم المنهى للخصومة كلها خلال الميعاد الذى اتفق عليه الطرفان . فإن لم يوجد اتفاق وجب أن يصدر الحكم خلال اثنى عشر شهرا من تاريخ بدء إجراءات التحكيم . وفى جميع الأحوال يجوز أن تقرر هيئة التحكيم مد الميعاد على إلا تزيد فترة المد على ستة أشهر ما لم يتفق الطرفان على مدة تزيد على ذلك .
( 2 ) واذا لم يصدر حكم التحكيم خلال الميعاد المشار اليه فى الفقرة السابقة جاز لأى من طرفى التحكيم أن يطلب من رئيس المحكمة المشار اليها فى المادة ( 9 ) من هذا القانون ، أن يصدر أمرا بتحديد ميعاد إضافى أو بإنهاء اجراءات التحكيم . ويكون لأى من الطرفين عندئذ رفع دعواه الى المحكمة المختصة أصلا بنظرها .$m240$,'5fb6abd0b79e4f1d6fc154ddc89a60fa',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(46,0,1,$m240$اذا عرضت خلال إجراءات التحكيم مسألة تخرج عن ولاية هيئة التحكيم أو طعن بالتزوير فى ورقة قدمت لها أو اتخذت اجراءات جنائية عن تزويرها أو عن فعل جنائى أخر ، جاز لهيئة التحكيم الاستمرار فى نظر موضوع النزاع إذا رأت أن الفصل فى هذه المسألة أو فى تزوير الورقة أو فى الفعل الجنائى الآخر ليس لازما للفصل فى موضوع النزاع ، والا أوقفت الإجراءات حتى يصدر حكم نهائى فى هذا الشأن ، ويترتب على ذلك وقف سريان الميعاد المحدد لإصدار حكم التحكيم .$m240$,'c8e91072ce9553c84790049b88ff1194',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(47,0,1,$m240$يجب على من صدر حكم التحكيم لصالحه إيداع أصل الحكم أو صورة موقعة منه باللغة التى صدر بها ، أو ترجمة باللغة العربية مصدقا عليها من جهة معتمدة اذا كان صادرا بلغة أجنبية ، وذلك فى قلم كتاب المحكمة المشار اليها فى المادة ( 9 ) من هذا القانون .
ويحرر كاتب المحكمة محضرا بهذا الإيداع ويجوز لكل من طرفى التحكيم طلب الحصول على صورة من هذا المحضر .$m240$,'40e83fb5a30e0c42dd978142ff5b5eaf',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(48,0,1,$m240$( 1 ) تنتهى إجراءات التحكيم بصدور الحكم المنهى للخصومة
كلها أو بصدور أمر بإنهاء اجراءات التحكيم وفقا للفقرة الثانية من المادة ( 45 ) من هذا القانون . كما تنتهى أيضا بصدور قرار من هيئة التحكيم بإنهاء الاجراءات فى الأحوال الآتية :
( أ ) إذا اتفق الطرفان على إنهاء التحكيم .
( ب ) إذا ترك المدعى خصومة التحكيم ما لم تقرر هيئة التحكيم ، بناء على طلب المدعى عليه ، أن له مصلحة جدية فى استمرار الإجراءات حتى يحسم النزاع .
( ج ) إذا رأت هيئة التحكيم لأى سبب آخر عدم جدوى استمرار اجراءات التحكيم أو استحالته .
( 2 ) مع مراعاة أحكام المواد 49 و 50 و 51 من هذا القانون تنتهى مهمة هيئة التحكيم بانتهاء اجراءات التحكيم .$m240$,'251fe7428974cf7a586c7c83aefc4384',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(49,0,1,$m240$( 1 ) يجوز لكل من طرفى التحكيم أن يطلب من هيئة التحكيم ، خلال الثلاثين يوما التالية لتسلمه حكم التحكيم ، تفسير ما وقع فى منطوقه من غموض . ويجب على طالب التفسير إعلان الطرف الآخر بهذا الطلب قبل تقديمه لهيئة التحكيم .
( 2 ) يصدر التفسير كتابة خلال الثلاثين يوما التالية لتاريخ تقديم طلب التفسير لهيئة التحكيم . ويجوز لهذه الهيئة مد هذا الميعاد ثلاثين يوما أخرى إذا رأت ضرورة لذلك .
( 3 ) ويعتبر الحكم الصادر بالتفسير متمما لحكم التحكيم الذى يفسره وتسرى عليه أحكامه .$m240$,'f329bc70ee14ff9d5c5040c2d2521398',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(50,0,1,$m240$( 1 ) تتولى هيئة التحكيم تصحيح ما يقع فى حكمها من أخطاء مادية بحتة ، كتابية أو حسابية ، وذلك بقرار تصدره من تلقاء نفسها أو بناء على طلب أحد الخصوم . وتجرى هيئة التحكيم التصحيح من غير مرافعة خلال الثلاثين يوما التالية لتاريخ صدور الحكم أو إيداع طلب التصحيح بحسب الأحوال . ولها مد هذا الميعاد ثلاثين يوما أخرى اذا رأت ضرورة لذلك .
( 2 ) ويصدر قرار التصحيح كتابة من هيئة التحكيم ويعلن إلى الطرفين خلال ثلاثين يوما من تاريخ صدوره واذا تجاوزت هيئة التحكيم سلطتها فى التصحيح جاز التمسك ببطلان هذا القرار بدعوى بطلان تسرى عليها أحكام المادتين ( 53 ) ، ( 54 ) من هذا القانون .$m240$,'a48e9a37d0a140b301c4f71f9c57b2ca',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(51,0,1,$m240$( 1 ) يجوز لكل من طرفى التحكيم ، ولو بعد انتهاء ميعاد التحكيم ، أن يطلب من هيئة التحكيم خلال الثلاثين يوما التالية لتسلمه حكم التحكيم إصدار حكم تحكيم إضافى فى طلبات قدمت خلال الاجراءات وأغفلها حكم التحكيم : ويجب إعلان هذا الطلب إلى الطرف الآخر قبل تقديمه .
( 2 ) وتصدر هيئة التحكيم حكمها خلال ستين يوما من تاريخ تقديم الطلب ويجوز لها مد هذا الميعاد ثلاثين يوما أخرى اذا رأت ضرورة لذلك .$m240$,'ac5ace089bb9108b0aea7c9536bcb1ca',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(52,0,1,$m240$( 1 ) لا تقبل أحكام التحكيم التى تصدر طبقا لأحكام هذا القانون الطعن فيها بأى طريق من طرق الطعن المنصوص عليها فى قانون المرافعات المدنية والتجارية .
( 2 ) يجوز رفع دعوى بطلان حكم التحكيم وفقا للأحكام المبينة فى المادتين التاليتين .$m240$,'724826421959405955665b3c28efc402',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(53,0,1,$m240$( 1 ) لا تقبل دعوى بطلان حكم التحكيم إلا فى الأحوال الآتية :
( أ ) إذا لم يوجد اتفاق تحكيم أو كان هذا الاتفاق باطلا أو قابلا للابطال أو سقط بانتهاء مدته .
( ب ) إذا كان أحد طرفى اتفاق التحكيم وقت إبرامه فاقد الأهلية أو ناقصها وفقا للقانون الذى يحكم أهليته .
( ج ) إذا تعذر على أحد طرفى التحكيم تقديم دفاعه بسبب عدم إعلانه إعلانا صحيحا بتعيين محكم أو بإجراءات التحكيم أو لأى سبب آخر خارج عن إرادته .
( د ) إذا استبعد حكم التحكيم تطبيق القانون الذى اتفق الأطراف على تطبيقه على موضوع النزاع .
( هـ ) إذا تم تشكيل هيئة التحكيم أو تعيين المحكمين على وجه مخالف للقانون أو لاتفاق الطرفين .
( و ) إذا فصل حكم التحكيم فى مسائل لا يشملها اتفاق التحكيم أو جاوز حدود هذا الاتفاق . ومع ذلك إذا أمكن فصل أجزاء الحكم الخاصة بالمسائل الخاضعة للتحكيم عن أجزائه الخاصة بالمسائل غير الخاضعة له فلا يقع البطلان إلا على الأجزاء الأخيرة وحدها .
( ز ) إذا وقع بطلان فى حكم التحكيم ، أو كانت إجراءات التحكيم باطلة بطلانا أثر فى الحكم .
( 2 ) وتقضى المحكمة التى تنظر دعوى البطلان من تلقاء نفسها ببطلان حكم التحكيم إذا تضمن ما يخالف النظام العام فى جمهورية مصر العربية .$m240$,'9865859cf97f806a3bd052521a1a3343',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(54,0,1,$m240$( 1 ) ترفع دعوى بطلان حكم التحكيم خلال التسعين يوما التالية لتاريخ إعلان حكم التحكيم للمحكوم عليه . ولا يحول دون قبول دعوى البطلان نزول مدعى البطلان عن حقه فى رفعها قبل صدور حكم التحكيم .
( 2 ) تختص بدعوى البطلان فى التحكيم التجارى الدولى المحكمة المشار اليها فى المادة ( 9 ) من هذا القانون . وفى غير التحكيم التجارى الدولى يكون الاختصاص لمحكمة الدرجة الثانية التى تتبعها المحكمة المختصة أصلا بنظر النزاع .$m240$,'e4913cba2a0321f15c8723b6375f4dbf',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(55,0,1,$m240$تحوز أحكام المحكمين الصادرة طبقا لهذا القانون حجية الأمر المقضى وتكون واجبة النفاذ بمراعاة الأحكام المنصوص عليها فى هذا القانون .$m240$,'4d216a5b848048b59e657957d4369b84',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(56,0,1,$m240$يختص رئيس المحكمة المشار اليها فى المادة ( 9 ) من هذا القانون أو من يندبه من قضاتها بإصدار الأمر بتنفيذ حكم المحكمين ، ويقدم طلب تنفيذ الحكم مرفقا به ما يلى :
1 - أصل الحكم أو صورة موقعة منه .
2 - صورة من اتفاق التحكيم .
3 - ترجمة مصدق عليها من جهة معتمدة إلى اللغة العربية لحكم التحكيم إذا لم يكن صادرا بها .
4 - صورة من المحضر الدال على إيداع الحكم وفقا للمادة ( 47 ) من هذا القانون .$m240$,'bfe6eb282a1640151495ffc81574c350',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(57,0,1,$m240$لا يترتب على رفع دعوى البطلان وقف تنفيذ حكم التحكيم ، ومع ذلك يجوز للمحكمة أن تأمر بوقف التنفيذ اذا طلب المدعى ذلك فى صحيفة الدعوى وكان الطلب مبنيا على أسباب جدية وعلى المحكمة الفصل فى طلب وقف التنفيذ خلال ستين يوما من تاريخ أول جلسة محددة لنظره ، وإذا أمرت بوقف التنفيذ جاز لها أن تأمر بتقديم كفالة أو ضمان مالى . وعليها إذا أمرت بوقف التنفيذ ، الفصل فى دعوى البطلان خلال ستة أشهر من تاريخ صدور هذا الأمر .$m240$,'b574e5bf0dd10d347dafd333385dc2a3',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL),
(58,0,1,$m240$( 1 ) لا يقبل طلب تنفيذ حكم التحكيم اذا لم يكن ميعاد رفع دعوى بطلان الحكم قد انقضى .
( 2 ) لا يجوز الأمر بتنفيذ حكم التحكيم وفقا لهذا القانون الا بعد التحقق مما يأتى :
( أ ) أنه لا يتعارض مع حكم سبق صدوره من المحاكم المصرية فى موضوع النزاع .
( ب ) أنه لا يتضمن ما يخالف النظام العام فى جمهورية مصر العربية .
( ج ) أنه قد تم إعلانه للمحكوم عليه إعلانا صحيحا .
( 3 ) ولا يجوز التظلم من الأمر الصادر بتنفيذ حكم التحكيم . أما الأمر الصادر برفض التنفيذ فيجوز التظلم منه إلى المحكمة المختصة وفقا لحكم المادة ( 9 ) من هذا القانون خلال ثلاثين يوما من تاريخ صدوره .$m240$,'1ec97de8546993d7e55bc8db60bcff12',DATE '1994-05-22',NULL,'active',NULL,NULL,NULL);

DO $m240$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m240_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m240_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[240] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m240_art) <> 63 OR (SELECT sum(char_length(body)) FROM m240_art) <> 24822 OR (SELECT count(*) FROM m240_ver) <> 63 THEN
    RAISE EXCEPTION '[240] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=27 AND law_year=1994 AND kind='law';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%التحكيم%' THEN
    RAISE EXCEPTION '[240] يوجد مستند آخر برقم 27 لسنة 1994 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (27, 1994, $t240$قانون رقم 27 لسنة 1994 بإصدار قانون فى شأن التحكيم فى المواد المدنية والتجارية$t240$, $t240$قانون التحكيم 27/1994$t240$, 'other', 'in_force', NULL, DATE '1994-04-18', NULL, 'EG', 'law', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m240_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m240_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m240_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 63 THEN
    RAISE EXCEPTION '[240] عدد صفوف النص % بدل 63', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 63 THEN
    RAISE EXCEPTION '[240] عدد نسخ النص % بدل 63', v_vcnt;
  END IF;
  RAISE NOTICE '[240] قانون 27/1994: جديد=%، صفوف مضافة=%، نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m240$;
